 if(members.some((b,i)=>b.boat_number!==i+1||!/^\d{4}$/.test(b.registration_number||''))||new Set(members.map(b=>b.registration_number)).size!==6)return null;
 const registration=members[0].registration_number,entry=PERIOD.records[registration];
 if(!entry)return null;
 if(!Number.isFinite(entry.r)||!Number.isInteger(entry.n)||entry.n<=0)return null;
 const c={date:day.date,key:key(r),value:String(entry.r),source:'OFFICIAL_PERIOD_FILE',sourceSha:PERIOD.sha256,registration,runs:entry.n,validFrom:PERIOD.validFrom,validThrough:PERIOD.validThrough,confirmed:true,confirmedAt:new Date(now).toISOString()};
