 if(c.date!==day.date||c.key!==key(r)||c.confirmed!==true||!Number.isFinite(stamp)||stamp>=cutoff||!/^(?:\d{1,2}|100)(?:\.\d{1,2})?$/.test(String(c.value))||Number(c.value)>100)fail('期別1コース率の値・対象・確認日時が不正です');
