  const one=day.members?.[key(r)]?.[0],entry=PERIOD.records[c.registration];
  if(day.date<PERIOD.validFrom||day.date>PERIOD.validThrough||c.validFrom!==PERIOD.validFrom||c.validThrough!==PERIOD.validThrough||c.sourceSha!==PERIOD.sha256||!one||one.registration_number!==c.registration||!entry||entry.n<=0||c.runs!==entry.n||Number(c.value)!==entry.r)fail('公式期別データの対象選手・適用期間・数値が不一致です');
